import XCTest
@testable import VishPrompt

/// Real Vision on committed screenshots. Run with `make verify-ocr`.
///
/// Gated because Vision's output can shift between macOS releases, and an ordinary `make test`
/// should not fail for that. The fixtures are committed and never regenerated by the test, so
/// they cannot drift towards being easy; `scripts/make-ocr-fixtures.swift` made them once.
final class ScreenshotOCRTests: XCTestCase {
    private static let isEnabled = ProcessInfo.processInfo.environment["VISHPROMPT_OCR"] == "1"

    override func setUpWithError() throws {
        try XCTSkipUnless(Self.isEnabled, "set VISHPROMPT_OCR=1 (make verify-ocr) to run the OCR tests")
    }

    private func fixture(_ name: String) throws -> Data {
        let url = try XCTUnwrap(Bundle(for: ScreenshotOCRTests.self).resourceURL)
            .appending(path: "Fixtures/ocr/\(name)")
        return try Data(contentsOf: url)
    }

    private let expected = [
        "npm test",
        "TypeError: Cannot read properties of undefined",
        "src/auth/refreshToken.ts:42:18",
        "Tests: 1 failed, 23 passed, 24 total",
    ]

    func testReadsATerminalScreenshot() async throws {
        let read = try await ScreenshotOCR.read(try fixture("terminal-error.png"))
        print("OCR terminal-error.png: \(read.lineCount) lines")
        for line in expected {
            XCTAssertTrue(read.text.contains(line), "missing “\(line)” in:\n\(read.text)")
        }
        XCTAssertGreaterThanOrEqual(read.lineCount, 7)
    }

    func testReadsTheSameScreenshotAfterJPEGCompression() async throws {
        let read = try await ScreenshotOCR.read(try fixture("terminal-error-jpeg.png"))
        for line in expected {
            XCTAssertTrue(read.text.contains(line), "missing “\(line)” after JPEG in:\n\(read.text)")
        }
    }

    /// The key in the image mixes O, o and 0 so OCR misreads it. However it comes back, the
    /// redactor must still remove it before anything could be sent.
    func testAMisreadKeyIsStillRedacted() async throws {
        for name in ["terminal-error.png", "terminal-error-jpeg.png"] {
            let read = try await ScreenshotOCR.read(try fixture(name))
            XCTAssertTrue(read.text.contains("ANTHROPIC_API_KEY"), "the key line was not read in \(name)")
            let redaction = Redactor.redact(read.text)
            XCTAssertFalse(redaction.isEmpty, "nothing redacted in \(name)")
            XCTAssertFalse(redaction.text.lowercased().contains("fake"), "the key survived in \(name):\n\(redaction.text)")
            XCTAssertFalse(redaction.text.contains("sk-ant"), "the key prefix survived in \(name)")
        }
    }

    /// Defeats a stubbed recogniser: a blank image must come back empty.
    func testABlankImageHasNoText() async throws {
        let read = try await ScreenshotOCR.read(try fixture("blank.png"))
        XCTAssertTrue(read.isEmpty, "read “\(read.text)” from a blank image")
        XCTAssertEqual(read.lineCount, 0)
    }

    func testGarbageIsRefused() async throws {
        do {
            _ = try await ScreenshotOCR.read(Data("not an image".utf8))
            XCTFail("expected unreadableImage")
        } catch {
            XCTAssertEqual(error as? ScreenshotOCRError, .unreadableImage)
        }
    }
}
